"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6431],{10447:e=>{e.exports=JSON.parse('{"functions":[{"name":"eligible","desc":"Sorted ids of the pool quests of `scope` \xd7 `category` whose Metric is live\\n(a key of QuestConfig.Metrics). A quest with a not-yet-wired metric is never offered.\\nA Personal quest also needs a metric reported with an actor\\n(QuestConfig.PersonalMetrics); party-only metrics never advance Personal quests.","params":[{"name":"scope","desc":"","lua_type":"Scope"},{"name":"category","desc":"","lua_type":"Category"}],"returns":[{"desc":"","lua_type":"{ string }\\n"}],"function_type":"static","source":{"line":59,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"fill","desc":"Top the offered list up to OFFER_SIZE with random eligible quests (fewer when\\nthe pool is small). Used at a reset.","params":[{"name":"box","desc":"","lua_type":"Box"},{"name":"scope","desc":"","lua_type":"Scope"},{"name":"category","desc":"","lua_type":"Category"},{"name":"rng","desc":"","lua_type":"Random"}],"returns":[],"function_type":"static","source":{"line":112,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"cancel","desc":"Move an accepted quest with no progress back to the end of the offered list,\\nkeeping its refresh count.","params":[{"name":"box","desc":"","lua_type":"Box"},{"name":"questId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":152,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"refreshCheck","desc":"Whether offered `questId` can be refreshed now: (code, isFree).","params":[{"name":"box","desc":"","lua_type":"Box"},{"name":"scope","desc":"","lua_type":"Scope"},{"name":"category","desc":"","lua_type":"Category"},{"name":"questId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number"},{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":169,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"refresh","desc":"Replace offered `questId` with a random other eligible quest; the slot\'s\\nrefresh count goes up by 1. The caller decides free vs paid (refreshCheck).","params":[{"name":"box","desc":"","lua_type":"Box"},{"name":"scope","desc":"","lua_type":"Scope"},{"name":"category","desc":"","lua_type":"Category"},{"name":"questId","desc":"","lua_type":"string"},{"name":"rng","desc":"","lua_type":"Random"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":184,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"advance","desc":"Add `amount` to every unfinished, unclaimed active quest of `category` with\\nMetric `metric`. A quest that reaches its Target stores `mult` (the Contract\\nBonus, locked at completion). Returns (changed, completedNow).","params":[{"name":"sd","desc":"","lua_type":"ScopeData"},{"name":"category","desc":"","lua_type":"Category"},{"name":"metric","desc":"","lua_type":"string"},{"name":"amount","desc":"","lua_type":"number"},{"name":"mult","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":201,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"claim","desc":"Claim a finished quest: marks it claimed, adds 1 mileage point (capped) and\\nreturns (code, coins, exp) with the stored multiplier applied.","params":[{"name":"sd","desc":"","lua_type":"ScopeData"},{"name":"scope","desc":"","lua_type":"Scope"},{"name":"category","desc":"","lua_type":"Category"},{"name":"questId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":221,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"sweep","desc":"The reset sweep: claim every finished quest, then every reached checkpoint\\n(the quests claimed here count toward mileage first). Returns what to pay.","params":[{"name":"sd","desc":"","lua_type":"ScopeData"},{"name":"scope","desc":"","lua_type":"Scope"}],"returns":[{"desc":"","lua_type":"{ Payout }\\n"}],"function_type":"static","source":{"line":258,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"boxPool","desc":"Sorted ids of every non-hidden Consumable or Expiring shop perk (the box pool).\\nSuperRareIds are left out: they have their own roll.","params":[{"name":"perks","desc":"","lua_type":"{ [string]: any }"}],"returns":[{"desc":"","lua_type":"{ string }\\n"}],"function_type":"static","source":{"line":281,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"rollBox","desc":"One perk box: (perkId, isSuperRare). The super rare roll only happens when\\nQuestBoardConfig.PerkBox.SuperRareIds is not empty.","params":[{"name":"rng","desc":"","lua_type":"Random"},{"name":"pool","desc":"","lua_type":"{ string }"}],"returns":[{"desc":"","lua_type":"string"},{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":297,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"boxOdds","desc":"The perk box odds the GUI must show, worked out from the pool the roll uses:\\neach normal perk = (1 - rare) / #pool, where rare = SuperRareChance only\\nwhile SuperRareIds is not empty. Groups come in board order (Personal\\nConsumable, Personal Expiring, Party Consumable, Party Expiring), names A\u2013Z.","params":[{"name":"perks","desc":"","lua_type":"{ [string]: any }"},{"name":"pool","desc":"","lua_type":"{ string }"}],"returns":[{"desc":"","lua_type":"BoxOdds\\n"}],"function_type":"static","source":{"line":311,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"recordPurchase","desc":"Record a processed PurchaseId (newest last, at most `cap` kept). Returns false\\nwhen it was already recorded (the receipt must not grant again).","params":[{"name":"list","desc":"","lua_type":"{ string }"},{"name":"purchaseId","desc":"","lua_type":"string"},{"name":"cap","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":355,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}},{"name":"nextPass","desc":"The slot pass to offer next: the first configured (non-zero) id in `ids` the\\nplayer does not own, or 0 when every configured pass is owned. Passes can be\\nbought in any order (also from the website), so a count is not enough.","params":[{"name":"ids","desc":"","lua_type":"{ number }"},{"name":"owned","desc":"","lua_type":"{ [number]: boolean }"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":371,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}}],"properties":[],"types":[],"name":"QuestBoardState","desc":"Pure quest board rules: offers, slots, accept, cancel, refresh, progress,\\nclaim, mileage checkpoints, the reset sweep, the perk box roll and receipt\\nidempotency. No instances, no services: every function takes the tables it\\nchanges, so Studio self-checks drive it with plain data. QuestManager (server)\\nis the only writer; GUIs read the same shapes from QuestClient.","source":{"line":11,"path":"src/ReplicatedStorage/SharedModules/QuestBoardState.luau"}}')}}]);